    ('dc:title', 'Title'),
    ('dc:subject', 'Subject'),
    ('dc:creator', 'Author'),
    ('cp:keywords', 'Keywords'),
    ('dc:description', 'Comments'),
    ('cp:lastModifiedBy', 'Last Modified By'),
    ('cp:revision', 'Revision'),
    ('dcterms:created', 'Created'),
    ('dcterms:modified', 'Modified'),
    ('cp:category', 'Category'),
    ('cp:contentStatus', 'Content Status'),
]

simple_app_tags = [
    'Application','AppVersion','Template','TotalTime','Pages','Words','Characters','CharactersWithSpaces',
    'Lines','Paragraphs','Company','Manager','DocSecurity','HyperlinksChanged','SharedDoc','LinksUpToDate',
    'ScaleCrop'
]

core_props = {}
app_props = {}
custom_props = {}

with ZipFile(docx_path) as z:
    # Core properties
    if 'docProps/core.xml' in z.namelist():
        root = ET.fromstring(z.read('docProps/core.xml'))
        for tag, label in core_map:
            el = root.find(tag, ns_core)
            if el is not None and (text := (el.text or '').strip()):
                core_props[label] = text
    # Extended properties
    if 'docProps/app.xml' in z.namelist():
        root = ET.fromstring(z.read('docProps/app.xml'))
        for t in simple_app_tags:
            el = root.find(f'ep:{t}', ns_app)
            if el is not None and (text := (el.text or '').strip()):
                app_props[t] = text
    # Custom properties
    if 'docProps/custom.xml' in z.namelist():
        root = ET.fromstring(z.read('docProps/custom.xml'))
        for prop in root.findall('cust:property', ns_custom):
            name = prop.get('name')
            # get text from first child element (vt:*)
            val = None
            for child in list(prop):
                if child.text and child.text.strip():
                    val = child.text.strip()
                    break
            if name and val is not None:
                custom_props[name] = val

lines = []
lines.append('Document Summary Metadata')
lines.append('')
if core_props:
    lines.append('[Core Properties]')
    for k in core_map:
        label = k[1]
        if label in core_props:
            lines.append(f'{label}: {core_props[label]}')
    # include any extra core props not in the standard map
    for k in sorted(set(core_props.keys()) - {lbl for _, lbl in core_map}):
        lines.append(f'{k}: {core_props[k]}')
    lines.append('')
if app_props:
    lines.append('[Extended Properties]')
    for k in simple_app_tags:
        if k in app_props:
            lines.append(f'{k}: {app_props[k]}')
    # extras
    for k in sorted(set(app_props.keys()) - set(simple_app_tags)):
        lines.append(f'{k}: {app_props[k]}')
    lines.append('')
if custom_props:
    lines.append('[Custom Properties]')
    for k in sorted(custom_props.keys()):
        lines.append(f'{k}: {custom_props[k]}')
    lines.append('')

if not (core_props or app_props or custom_props):
    lines.append('(No metadata found)')

out_path.write_text('\n'.join(lines), encoding='utf-8')
print(f'Wrote {out_path} ({len(lines)} lines) at {datetime.now().isoformat()}')
